// Phase 1 — Build run metadata for every execution
const input = $input.first().json || {};
const mode = input.mode === 'scheduled' ? 'scheduled' : 'manual';

const now = new Date();
const timezone = 'Asia/Kolkata';

const runDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const triggeredAt = now.toISOString();
const runId = typeof crypto !== 'undefined' && crypto.randomUUID
  ? crypto.randomUUID()
  : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      const v = c === 'x' ? r : (r & 0x3) | 0x8;
      return v.toString(16);
    });

return [
  {
    json: {
      runId,
      runDate,
      triggeredAt,
      mode,
      timezone,
    },
  },
];

// Phase 1 — Central config (generated from config/sources.json)
// Re-run: node workflows/scripts/generate-phase4-workflow.js
const run = $input.first().json;

const config = {
  "timezone": "Asia/Kolkata",
  "maxArticlesPerSource": 2,
  "maxArticlesTotal": 10,
  "llm": {
    "provider": "gemini",
    "model": "gemini-3.5-flash-lite",
    "thinkingLevel": "minimal",
    "categorizeBatchSize": 10,
    "maxContentChars": 500,
    "minConfidence": 0.35,
    "maxRetries": 1,
    "timeoutMs": 60000,
    "maxRequestsPerRun": 16,
    "minRequestGapMs": 4200,
    "rateLimits": {
      "requestsPerMinute": 15,
      "tokensPerMinute": 250000,
      "requestsPerDay": 500
    },
    "notes": "Gemini 3.5 Flash Lite. n8n: set Variable GEMINI_API_KEY ($vars.GEMINI_API_KEY). Client enforces ~4.2s gap (15 RPM), TPM estimate, 16 req/run (~384/day at hourly) under 500 RPD."
  },
  "website": {
    "publishUrl": "http://localhost:4000/api/summary",
    "publishMethod": "PUT",
    "authHeaderTemplate": "Authorization: Bearer <PUBLISH_API_KEY>",
    "apiKeyCredentialHint": "Store PUBLISH_API_KEY in n8n credentials / Header Auth; do not hardcode."
  },
  "categories": [
    "Politics",
    "Sports",
    "Business",
    "Technology",
    "Entertainment",
    "Health",
    "Education",
    "Crime",
    "Weather",
    "World"
  ],
  "sources": [
    {
      "id": "india_today",
      "name": "India Today",
      "type": "rss",
      "url": "https://www.indiatoday.in/",
      "rssUrl": "https://www.indiatoday.in/rss/1206578",
      "enabled": true
    },
    {
      "id": "ndtv_india",
      "name": "NDTV",
      "type": "rss",
      "url": "https://www.ndtv.com/india",
      "rssUrl": "https://feeds.feedburner.com/ndtvnews-india-news",
      "enabled": true
    },
    {
      "id": "toi_india",
      "name": "Times of India",
      "type": "rss",
      "url": "https://timesofindia.indiatimes.com/india",
      "rssUrl": "https://timesofindia.indiatimes.com/rssfeeds/-2128936835.cms",
      "enabled": true
    },
    {
      "id": "ht_india",
      "name": "Hindustan Times",
      "type": "rss",
      "url": "https://www.hindustantimes.com/india-news",
      "rssUrl": "https://www.hindustantimes.com/feeds/rss/india-news/rssfeed.xml",
      "enabled": true
    },
    {
      "id": "ie_india",
      "name": "Indian Express",
      "type": "rss",
      "url": "https://indianexpress.com/section/india/",
      "rssUrl": "https://indianexpress.com/section/india/feed/",
      "enabled": true
    }
  ]
};

const enabledSources = config.sources.filter((s) => s.enabled);

return [
  {
    json: {
      ...run,
      config: {
        ...config,
        enabledSourceCount: enabledSources.length,
      },
      phase: 'phase6-ready',
      nextPhaseHint: 'Collect → normalize → AI → format → publish',
    },
  },
];

// Phase 2 — Collect from every enabled source in one node
// (avoids HTTP fan-out pairedItem bugs that can mis-label all items as the first source)
function decodeEntities(text) {
  if (!text) return "";
  return String(text)
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)));
}

function stripHtml(html) {
  if (!html) return "";
  return decodeEntities(
    String(html)
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<[^>]+>/g, " ")
      .replace(/\s+/g, " ")
      .trim()
  );
}

function truncate(text, maxLen) {
  const s = String(text || "").trim();
  if (!maxLen || s.length <= maxLen) return s;
  return s.slice(0, maxLen - 1).trimEnd() + "…";
}

function canonicalizeUrl(rawUrl) {
  if (!rawUrl) return "";
  let s = String(rawUrl).trim().replace(/\s+/g, "");
  if (!s) return "";
  try {
    const u = new URL(s);
    const drop = [];
    for (const key of u.searchParams.keys()) {
      if (/^utm_/i.test(key) || key === "fbclid" || key === "gclid") drop.push(key);
    }
    drop.forEach((k) => u.searchParams.delete(k));
    if (u.hash && /publisher=/i.test(u.hash)) u.hash = "";
    u.hostname = u.hostname.toLowerCase();
    let out = u.toString();
    if (out.endsWith("/") && u.pathname !== "/" && !u.search && !u.hash) {
      out = out.slice(0, -1);
    }
    return out;
  } catch {
    return s;
  }
}

function hashArticleId(sourceId, canonicalUrl) {
  const payload = `${sourceId}|${canonicalUrl}`;
  if (typeof crypto !== "undefined" && crypto.createHash) {
    return crypto.createHash("sha256").update(payload).digest("hex").slice(0, 24);
  }
  // Fallback FNV-1a 64-bit hex (rare — n8n Node has crypto)
  let h = 0xcbf29ce484222325n;
  const data = Buffer.from(payload);
  for (let i = 0; i < data.length; i++) {
    h ^= BigInt(data[i]);
    h = (h * 0x100000001b3n) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, "0");
}

function unwrapCdata(value) {
  if (!value) return "";
  const s = String(value).trim();
  const m = s.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/i);
  return m ? m[1].trim() : s;
}

function tagContent(block, tagNames) {
  const names = Array.isArray(tagNames) ? tagNames : [tagNames];
  for (const name of names) {
    const re = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${name}>`, "i");
    const m = block.match(re);
    if (m) return unwrapCdata(m[1]);
  }
  return "";
}

function selfClosingAttr(block, tagName, attrName) {
  const re = new RegExp(
    `<${tagName}\\b[^>]*\\b${attrName}=["']([^"']+)["'][^>]*\\/?>`,
    "i"
  );
  const m = block.match(re);
  return m ? m[1].trim() : "";
}

function parsePublishedAt(raw) {
  if (!raw) return null;
  const cleaned = unwrapCdata(raw).trim();
  if (!cleaned) return null;
  const d = new Date(cleaned);
  if (Number.isNaN(d.getTime())) return null;
  return d.toISOString();
}

function parseFeed(xml) {
  const text = String(xml || "");
  const chunks = [];
  let m;
  const itemRe = /<item\b[^>]*>([\s\S]*?)<\/item>/gi;
  while ((m = itemRe.exec(text)) !== null) chunks.push({ kind: "rss", body: m[1] });
  if (chunks.length === 0) {
    const entryRe = /<entry\b[^>]*>([\s\S]*?)<\/entry>/gi;
    while ((m = entryRe.exec(text)) !== null) chunks.push({ kind: "atom", body: m[1] });
  }

  return chunks.map(({ kind, body }) => {
    let title = stripHtml(tagContent(body, "title"));
    let link = "";
    let publishedAt = null;
    let snippet = "";
    let content = "";

    if (kind === "atom") {
      link =
        selfClosingAttr(body, "link", "href") ||
        tagContent(body, "link") ||
        tagContent(body, "id");
      publishedAt = parsePublishedAt(tagContent(body, ["published", "updated"]));
      snippet = stripHtml(tagContent(body, ["summary", "content"]) || "");
      content = truncate(snippet, 2000);
    } else {
      link =
        tagContent(body, "link") ||
        selfClosingAttr(body, "link", "href") ||
        tagContent(body, "guid");
      publishedAt = parsePublishedAt(tagContent(body, "pubDate"));
      const description = tagContent(body, "description");
      const encoded = tagContent(body, ["content:encoded", "content"]);
      snippet = stripHtml(description || encoded || "");
      content = truncate(stripHtml(encoded || description || ""), 2000);
    }

    return {
      title: decodeEntities(title).trim(),
      url: unwrapCdata(link).trim(),
      publishedAt,
      snippet: truncate(snippet, 500),
      content,
    };
  });
}

function parseHtmlListing(html, baseUrl) {
  const text = String(html || "");
  const results = [];
  const seen = new Set();
  const re = /<a\b[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    let href = m[1].trim();
    const title = stripHtml(m[2]);
    if (!title || title.length < 25) continue;
    try {
      href = new URL(href, baseUrl).toString();
    } catch {
      continue;
    }
    if (!/^https?:\/\//i.test(href)) continue;
    if (seen.has(href)) continue;
    seen.add(href);
    results.push({ title, url: href, publishedAt: null, snippet: "", content: "" });
    if (results.length >= 40) break;
  }
  return results;
}

function toArticle(source, raw, fetchedAt) {
  const title = (raw.title || "").trim();
  const url = canonicalizeUrl(raw.url);
  if (!title || !url || !/^https?:\/\//i.test(url)) return null;
  // Some feeds (e.g. Indian Express) ship empty descriptions — fall back to title.
  const snippet = truncate(raw.snippet || title, 500);
  const content = truncate(raw.content || snippet, 2000);
  return {
    id: hashArticleId(source.id, url),
    sourceId: source.id,
    sourceName: source.name,
    title,
    url,
    publishedAt: raw.publishedAt || null,
    snippet,
    content,
    fetchedAt,
  };
}

function extractArticlesFromFetch(source, opts) {
  const fetchedAt = opts.fetchedAt || new Date().toISOString();
  const max = Math.max(1, Number(opts.maxArticlesPerSource) || 8);
  const statusCode = opts.statusCode == null ? null : opts.statusCode;
  const errorMsg = opts.error ? String(opts.error) : null;
  const body = opts.body == null ? "" : String(opts.body);

  const baseStatus = {
    sourceId: source.id,
    sourceName: source.name,
    fetchMode: source.rssUrl ? "rss" : "html",
    fetchUrl: source.rssUrl || source.url,
    statusCode,
  };

  if (errorMsg) {
    return {
      articles: [],
      sourceStatus: {
        ...baseStatus,
        status: "failed",
        error: errorMsg,
        articleCount: 0,
      },
    };
  }

  if (statusCode != null && (statusCode < 200 || statusCode >= 300)) {
    return {
      articles: [],
      sourceStatus: {
        ...baseStatus,
        status: "failed",
        error: `HTTP ${statusCode}`,
        articleCount: 0,
      },
    };
  }

  if (!body.trim()) {
    return {
      articles: [],
      sourceStatus: {
        ...baseStatus,
        status: "failed",
        error: "Empty response body",
        articleCount: 0,
      },
    };
  }

  let rawItems;
  try {
    if (source.rssUrl) {
      rawItems = parseFeed(body);
      if (rawItems.length === 0) {
        rawItems = parseHtmlListing(body, source.url || source.rssUrl);
        baseStatus.fetchMode = rawItems.length ? "html-fallback" : "rss";
      }
    } else {
      rawItems = parseHtmlListing(body, source.url);
    }
  } catch (err) {
    return {
      articles: [],
      sourceStatus: {
        ...baseStatus,
        status: "failed",
        error: `Parse error: ${err && err.message ? err.message : String(err)}`,
        articleCount: 0,
      },
    };
  }

  const articles = [];
  const seenIds = new Set();
  for (const raw of rawItems) {
    const article = toArticle(source, raw, fetchedAt);
    if (!article) continue;
    if (seenIds.has(article.id)) continue;
    seenIds.add(article.id);
    articles.push(article);
    if (articles.length >= max) break;
  }

  if (articles.length === 0) {
    return {
      articles: [],
      sourceStatus: {
        ...baseStatus,
        status: "failed",
        error: "No articles extracted",
        articleCount: 0,
      },
    };
  }

  return {
    articles,
    sourceStatus: {
      ...baseStatus,
      status: "success",
      error: null,
      articleCount: articles.length,
    },
  };
}


const ctx = $input.first().json || {};
const config = ctx.config || {};
const sources = (config.sources || []).filter((s) => s.enabled);
const maxArticlesPerSource = config.maxArticlesPerSource || 2;
const fetchedAt = new Date().toISOString();
const delayMs = 200;

const articles = [];
const sourceStatuses = [];

async function fetchOne(url) {
  const maxAttempts = 3;
  const backoffMs = [1000, 2500];

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url,
        headers: {
          'User-Agent':
            'Mozilla/5.0 (compatible; IndiaNewsSummarizer/0.7; +n8n)',
          Accept:
            'application/rss+xml, application/atom+xml, application/xml, text/xml, text/html;q=0.9, */*;q=0.8',
        },
        returnFullResponse: true,
        timeout: 20000,
        ignoreHttpStatusErrors: true,
      });

      const statusCode = res.statusCode ?? res.status ?? null;
      let body = res.body ?? res.data ?? '';
      if (body && typeof body === 'object') {
        body = typeof body === 'string' ? body : JSON.stringify(body);
      }
      body = body == null ? '' : String(body);

      const retriable =
        statusCode == null || statusCode === 408 || statusCode === 429 || statusCode >= 500;
      if (retriable && attempt < maxAttempts - 1) {
        await new Promise((r) => setTimeout(r, backoffMs[attempt] || 2500));
        continue;
      }

      return { statusCode, body, error: null, attempts: attempt + 1 };
    } catch (err) {
      if (attempt < maxAttempts - 1) {
        await new Promise((r) => setTimeout(r, backoffMs[attempt] || 2500));
        continue;
      }
      return {
        statusCode: null,
        body: '',
        error: (err && err.message) || String(err),
        attempts: attempt + 1,
      };
    }
  }

  return {
    statusCode: null,
    body: '',
    error: 'fetch_exhausted',
    attempts: maxAttempts,
  };
}

for (let i = 0; i < sources.length; i++) {
  const source = sources[i];
  const fetchUrl = source.rssUrl || source.url;
  const fetched = await fetchOne.call(this, fetchUrl);
  const { articles: batch, sourceStatus } = extractArticlesFromFetch(source, {
    body: fetched.body,
    statusCode: fetched.statusCode,
    error: fetched.error,
    maxArticlesPerSource,
    fetchedAt,
  });
  articles.push(...batch);
  sourceStatuses.push(sourceStatus);

  if (delayMs > 0 && i < sources.length - 1) {
    await new Promise((r) => setTimeout(r, delayMs));
  }
}

const sourcesConfigured = (config.sources || []).length;
const sourcesEnabled = sources.length;
const sourcesSucceeded = sourceStatuses.filter((s) => s.status === 'success').length;
const sourcesFailed = sourceStatuses.filter((s) => s.status === 'failed').length;
const failedSources = sourceStatuses
  .filter((s) => s.status === 'failed')
  .map((s) => ({
    sourceId: s.sourceId,
    sourceName: s.sourceName,
    error: s.error,
  }));

return [
  {
    json: {
      runId: ctx.runId,
      runDate: ctx.runDate,
      triggeredAt: ctx.triggeredAt,
      mode: ctx.mode,
      timezone: ctx.timezone,
      config,
      articles,
      sourceStatuses,
      collection: {
        sourcesConfigured,
        sourcesEnabled,
        sourcesSucceeded,
        sourcesFailed,
        articleCount: articles.length,
        failedSources,
        maxArticlesPerSource,
      },
      phase: 'phase2-collection',
      nextPhaseHint: 'Phase 3 normalize / dedupe / empty-run guard',
    },
  },
];

// Phase 3 — Normalize, exact+near dedupe, cap, emit corpus stats + guard
function decodeEntities(text) {
  if (!text) return "";
  return String(text)
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)));
}

function cleanText(value) {
  return decodeEntities(String(value || ""))
    .replace(/\s+/g, " ")
    .trim();
}

const TRACKING_PARAM =
  /^(utm_|fbclid$|gclid$|mc_eid$|mc_cid$|_ga$|igshid$|spm$|scm$|ncid$|cmpid$|ocid$)/i;

function canonicalizeUrl(rawUrl) {
  if (!rawUrl) return "";
  let s = String(rawUrl).trim().replace(/\s+/g, "");
  if (!s) return "";
  try {
    const u = new URL(s);
    const drop = [];
    for (const key of u.searchParams.keys()) {
      if (TRACKING_PARAM.test(key)) drop.push(key);
    }
    drop.forEach((k) => u.searchParams.delete(k));
    if (u.hash && (/publisher=/i.test(u.hash) || /^#?utm_/i.test(u.hash))) {
      u.hash = "";
    }
    u.hostname = u.hostname.toLowerCase();
    if (
      u.protocol === "http:" &&
      u.hostname !== "localhost" &&
      u.hostname !== "127.0.0.1"
    ) {
      u.protocol = "https:";
    }
    let out = u.toString();
    if (out.endsWith("/") && u.pathname !== "/" && !u.search && !u.hash) {
      out = out.slice(0, -1);
    }
    return out;
  } catch {
    return s;
  }
}

function toAsiaKolkataIso(input) {
  if (input == null || input === "") return null;
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return null;
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(d)
      .filter((p) => p.type !== "literal")
      .map((p) => [p.type, p.value])
  );
  return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}+05:30`;
}

const STOPWORDS = new Set([
  "a", "an", "the", "and", "or", "of", "to", "in", "on", "for", "with", "at",
  "by", "from", "as", "is", "are", "was", "were", "be", "been", "after",
  "before", "over", "under", "into", "about", "against", "between", "through",
  "during", "without", "within", "via", "vs", "vs.", "says", "said", "amid",
  "its", "his", "her", "their", "new", "latest", "live", "update", "updates",
  "breaking",
]);

function normalizeTitle(title) {
  return String(title || "")
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[^a-z0-9\s']/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function titleTokens(title) {
  return normalizeTitle(title)
    .split(" ")
    .map((t) => t.replace(/^'+|'+$/g, ""))
    .filter((t) => t.length > 1 && !STOPWORDS.has(t));
}

function jaccard(aTokens, bTokens) {
  if (!aTokens.length || !bTokens.length) return 0;
  const a = new Set(aTokens);
  const b = new Set(bTokens);
  let inter = 0;
  for (const t of a) if (b.has(t)) inter += 1;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}

function titlesNearDuplicate(titleA, titleB, threshold) {
  const thr = threshold == null ? 0.72 : threshold;
  const a = titleTokens(titleA);
  const b = titleTokens(titleB);
  const score = jaccard(a, b);
  if (score >= thr) return { match: true, score };
  const shorter = a.length <= b.length ? a : b;
  const longer = a.length <= b.length ? b : a;
  if (shorter.length >= 4) {
    const longerSet = new Set(longer);
    const hit = shorter.filter((t) => longerSet.has(t)).length;
    const containment = hit / shorter.length;
    if (containment >= 0.9 && score >= 0.55) {
      return { match: true, score: Math.max(score, containment) };
    }
  }
  return { match: false, score };
}

function sourceRankMap(sources) {
  const map = new Map();
  (sources || []).forEach((s, i) => {
    if (s && s.id) map.set(s.id, i);
  });
  return map;
}

function richnessScore(article, sourceRank) {
  const snippetLen = (article.snippet || "").length;
  const contentLen = (article.content || "").length;
  const hasDate = article.publishedAt ? 1 : 0;
  const rank = sourceRank.has(article.sourceId)
    ? sourceRank.get(article.sourceId)
    : 999;
  return snippetLen + contentLen + hasDate * 200 - rank * 5;
}

function normalizeArticle(raw) {
  const title = cleanText(raw.title);
  const url = canonicalizeUrl(raw.url);
  const snippet = cleanText(raw.snippet);
  const content = cleanText(raw.content);
  const publishedAt = toAsiaKolkataIso(raw.publishedAt);
  const fetchedAt = toAsiaKolkataIso(raw.fetchedAt) || raw.fetchedAt || null;
  if (!title || !url) return null;
  return {
    id: raw.id,
    sourceId: raw.sourceId,
    sourceName: raw.sourceName,
    title,
    url,
    publishedAt,
    snippet,
    content: content || snippet,
    fetchedAt,
  };
}

function exactDedupe(articles, sourceRank) {
  const byKey = new Map();
  let dropped = 0;
  for (const a of articles) {
    const key = a.url || a.id;
    if (!key) continue;
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, a);
      continue;
    }
    dropped += 1;
    if (richnessScore(a, sourceRank) > richnessScore(existing, sourceRank)) {
      byKey.set(key, a);
    }
  }
  const byId = new Map();
  for (const a of byKey.values()) {
    const existing = byId.get(a.id);
    if (!existing) {
      byId.set(a.id, a);
      continue;
    }
    dropped += 1;
    if (richnessScore(a, sourceRank) > richnessScore(existing, sourceRank)) {
      byId.set(a.id, a);
    }
  }
  return { articles: [...byId.values()], dropped };
}

function nearDedupe(articles, sourceRank, threshold) {
  const thr = threshold == null ? 0.72 : threshold;
  const kept = [];
  let dropped = 0;
  const ordered = [...articles].sort(
    (a, b) => richnessScore(b, sourceRank) - richnessScore(a, sourceRank)
  );
  for (const candidate of ordered) {
    let dupOf = null;
    for (const existing of kept) {
      const { match } = titlesNearDuplicate(candidate.title, existing.title, thr);
      if (match) {
        dupOf = existing;
        break;
      }
    }
    if (dupOf) {
      dropped += 1;
      if (richnessScore(candidate, sourceRank) > richnessScore(dupOf, sourceRank)) {
        kept[kept.indexOf(dupOf)] = candidate;
      }
      continue;
    }
    kept.push(candidate);
  }
  return { articles: kept, dropped };
}

function capArticles(articles, maxTotal) {
  const max = Math.max(1, Number(maxTotal) || 40);
  const sorted = [...articles].sort((a, b) => {
    const ta = a.publishedAt ? Date.parse(a.publishedAt) : 0;
    const tb = b.publishedAt ? Date.parse(b.publishedAt) : 0;
    if (tb !== ta) return tb - ta;
    return (b.fetchedAt || "").localeCompare(a.fetchedAt || "");
  });
  const capped = sorted.slice(0, max);
  return { articles: capped, dropped: Math.max(0, sorted.length - capped.length) };
}

function buildCorpus(rawArticles, options) {
  options = options || {};
  const sourceRank = sourceRankMap(options.sources);
  const maxArticlesTotal = options.maxArticlesTotal == null ? 40 : options.maxArticlesTotal;
  const threshold =
    options.nearDuplicateThreshold == null ? 0.72 : options.nearDuplicateThreshold;
  const sourceStatuses = options.sourceStatuses || [];

  const normalized = [];
  for (const raw of rawArticles || []) {
    const a = normalizeArticle(raw);
    if (a) normalized.push(a);
  }

  const exact = exactDedupe(normalized, sourceRank);
  const near = nearDedupe(exact.articles, sourceRank, threshold);
  const capped = capArticles(near.articles, maxArticlesTotal);

  const sourceSuccessCount = sourceStatuses.filter((s) => s.status === "success").length;
  const sourceFailedCount = sourceStatuses.filter((s) => s.status === "failed").length;
  const failedSources = sourceStatuses
    .filter((s) => s.status === "failed")
    .map((s) => ({
      sourceId: s.sourceId,
      sourceName: s.sourceName,
      error: s.error,
    }));

  const articleCount = capped.articles.length;
  const dedupedCount = exact.dropped + near.dropped;

  return {
    articles: capped.articles,
    stats: {
      rawCount: (rawArticles || []).length,
      normalizedCount: normalized.length,
      exactDedupedCount: exact.dropped,
      nearDedupedCount: near.dropped,
      dedupedCount,
      cappedCount: capped.dropped,
      articleCount,
      sourceSuccessCount,
      sourceFailedCount,
      failedSources,
      nearDuplicateThreshold: threshold,
      maxArticlesTotal,
    },
    guard: {
      proceed: articleCount > 0,
      reason: articleCount > 0 ? null : "empty_corpus",
      skipLlm: articleCount === 0,
      skipPublish: articleCount === 0,
    },
  };
}


const input = $input.first().json || {};
const config = input.config || {};
const rawArticles = Array.isArray(input.articles) ? input.articles : [];
const sourceStatuses = Array.isArray(input.sourceStatuses) ? input.sourceStatuses : [];

const corpusResult = buildCorpus(rawArticles, {
  sources: config.sources || [],
  maxArticlesTotal: config.maxArticlesTotal || 40,
  sourceStatuses,
});

const collection = input.collection || {};

return [
  {
    json: {
      runId: input.runId,
      runDate: input.runDate,
      triggeredAt: input.triggeredAt,
      mode: input.mode,
      timezone: input.timezone || config.timezone || 'Asia/Kolkata',
      config,
      sourceStatuses,
      collection,
      articles: corpusResult.articles,
      corpus: corpusResult.stats,
      guard: corpusResult.guard,
      articleCount: corpusResult.stats.articleCount,
      dedupedCount: corpusResult.stats.dedupedCount,
      sourceSuccessCount: corpusResult.stats.sourceSuccessCount,
      phase: 'phase3-normalize',
      nextPhaseHint: corpusResult.guard.proceed
        ? 'Phase 4 will categorize and summarize with Gemini'
        : 'Empty corpus — skipped LLM and publish (keep last good website summary)',
    },
