function aiExtractGeminiText(data) {
  const parts =
    data &&
    data.candidates &&
    data.candidates[0] &&
    data.candidates[0].content &&
    data.candidates[0].content.parts;
  if (!Array.isArray(parts) || !parts.length) {
    const err = new Error("gemini_empty_candidates");
    err.code = "gemini_empty_candidates";
    throw err;
  }
  const texts = parts
    .filter(function (p) {
      return p && p.text && !p.thought;
    })
    .map(function (p) {
      return p.text;
    });
  return (texts.length
    ? texts
    : parts.map(function (p) {
        return p.text || "";
      })
  )
    .join("")
    .trim();
}

async function aiGeminiGenerate(prompt, options) {
  const apiKey = (options && options.apiKey) || "";
  if (!apiKey) {
    const err = new Error("missing_gemini_api_key");
    err.code = "missing_gemini_api_key";
    throw err;
  }
  const model = (options && options.model) || AI_DEFAULT_MODEL;
  const thinkingLevel =
    (options && options.thinkingLevel) || "minimal";
  const url =
    "https://generativelanguage.googleapis.com/v1beta/models/" +
    encodeURIComponent(model) +
    ":generateContent?key=" +
    encodeURIComponent(apiKey);

  const body = {
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: {
      responseMimeType: "application/json",
      thinkingConfig: {
        thinkingLevel: String(thinkingLevel).toLowerCase(),
      },
    },
  };

  const httpRequest = options.httpRequest;
  const res = await httpRequest({
    method: "POST",
    url: url,
    headers: { "Content-Type": "application/json" },
    body: body,
    json: true,
    timeout: (options && options.timeout) || 60000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });

  const statusCode = res.statusCode != null ? res.statusCode : res.status || 0;
  let data = res.body != null ? res.body : res.data;
  if (typeof data === "string") {
    try {
      data = JSON.parse(data);
    } catch (_) {}
  }
  if (statusCode < 200 || statusCode >= 300) {
    const err = new Error(
      "gemini_http_" +
        statusCode +
        ": " +
        (typeof data === "string"
          ? data.slice(0, 200)
          : JSON.stringify(data).slice(0, 200))
    );
    err.code = "gemini_http_error";
    err.statusCode = statusCode;
    throw err;
  }
  return aiExtractGeminiText(data);
}

async function aiWithRetry(fn, maxRetries) {
  const attempts = Math.max(0, Number(maxRetries) || 0) + 1;
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn(i);
    } catch (err) {
      lastErr = err;
      const status = err && err.statusCode;
      if (i < attempts - 1) {
        const wait =
          status === 429
            ? Math.min(60000, (Math.ceil(60000 / AI_DEFAULT_RPM) + 500) * (i + 1))
            : Math.min(10000, 500 * Math.pow(2, i));
        await aiSleep(wait);
      }
    }
  }
  throw lastErr;
}

/**
 * Full Stage A + B for n8n Code node.
 * options: { categories, llm config fields, apiKey, httpRequest, mock }
 */
async function aiRunPipeline(articles, options) {
  options = options || {};
  const categories = options.categories || AI_DEFAULT_CATEGORIES;
  const llm = options.llm || {};
  const model = llm.model || AI_DEFAULT_MODEL;
  const batchSize = llm.categorizeBatchSize || 10;
  const maxContentChars = llm.maxContentChars || 500;
  const minConfidence =
    typeof llm.minConfidence === "number" ? llm.minConfidence : 0.35;
  const maxRetries = typeof llm.maxRetries === "number" ? llm.maxRetries : 1;
  const thinkingLevel = llm.thinkingLevel || "minimal";
  const useMock = Boolean(options.mock);
  const rateLimits = Object.assign(
    {
      requestsPerMinute: AI_DEFAULT_RPM,
      tokensPerMinute: AI_DEFAULT_TPM,
      requestsPerDay: AI_DEFAULT_RPD,
    },
    llm.rateLimits || {}
  );
  if (typeof llm.maxRequestsPerRun === "number") {
    rateLimits.maxRequestsPerRun = llm.maxRequestsPerRun;
  }
  if (typeof llm.minRequestGapMs === "number") {
    rateLimits.minRequestGapMs = llm.minRequestGapMs;
  }
  const limiter = useMock ? null : aiCreateRateLimiter(rateLimits);

  const callLlm = async function (prompt, mockText) {
    if (useMock) return mockText;
    if (limiter) await limiter.acquire(aiEstimateTokens(prompt, 800));
    return aiGeminiGenerate(prompt, {
      apiKey: options.apiKey,
      model: model,
      thinkingLevel: thinkingLevel,
      httpRequest: options.httpRequest,
      timeout: llm.timeoutMs || 60000,
    });
  };

  const batches = aiBatchArticles(articles, batchSize);
  const allAssignments = [];
  const errors = [];
  const skipped = [];

  for (let bi = 0; bi < batches.length; bi++) {
    if (limiter && limiter.remainingRunBudget() <= 0) {
      errors.push({
        stage: "categorize",
        batch: bi,
        error: "rate_limit_run budget exhausted",
        code: "rate_limit_run",
      });
      break;
    }
    const batch = batches[bi];
    const prompt = aiBuildCategorizePrompt(batch, {
      categories: categories,
      maxContentChars: maxContentChars,
    });
    try {
      const text = await aiWithRetry(async function () {
        const raw = await callLlm(prompt, aiMockCategorizeText(batch, categories));
        const parsed = aiExtractJsonObject(raw);
        if (!parsed || !Array.isArray(parsed.assignments)) {
          const err = new Error("categorize_missing_assignments");
          err.code = "categorize_missing_assignments";
          throw err;
        }
        return raw;
      }, maxRetries);
      const parsed = aiExtractJsonObject(text);
      allAssignments.push.apply(allAssignments, parsed.assignments);
    } catch (err) {
      errors.push({
        stage: "categorize",
        batch: bi,
        error: (err && err.message) || String(err),
        code: err && err.code,
      });
      if (options.fallbackMockOnError || useMock) {
        const parsed = aiExtractJsonObject(
          aiMockCategorizeText(batch, categories)
        );
        allAssignments.push.apply(allAssignments, parsed.assignments);
      }
    }
  }

  const applied = aiApplyCategorization(
    articles,
    { assignments: allAssignments },
    { categories: categories, minConfidence: minConfidence }
  );
  let groups = aiGroupByCategory(applied.articles, categories);
  const sumResults = [];

  if (limiter) {
    const budget = limiter.remainingRunBudget();
    const maxGroups = Math.max(0, Math.floor(budget / (maxRetries + 1)));
    if (maxGroups < groups.length) {
      const ordered = groups.slice().sort(function (a, b) {
        return (b.articles || []).length - (a.articles || []).length;
      });
      const chosen = ordered.slice(0, maxGroups);
      const chosenSet = {};
      chosen.forEach(function (g) {
        chosenSet[g.category] = true;
      });
      groups.forEach(function (g) {
        if (!chosenSet[g.category]) {
          skipped.push({
            category: g.category,
            reason: "rate_limit_run",
            articleCount: (g.articles || []).length,
          });
        }
      });
      groups = chosen;
    }
  }

  for (let gi = 0; gi < groups.length; gi++) {
    const group = groups[gi];
    if (limiter && limiter.remainingRunBudget() <= 0) {
      skipped.push({
        category: group.category,
        reason: "rate_limit_run",
        articleCount: (group.articles || []).length,
      });
      continue;
    }
    const prompt = aiBuildSummarizePrompt(group.category, group.articles, {
      maxContentChars: maxContentChars,
    });
    try {
      const text = await aiWithRetry(async function () {
        const raw = await callLlm(
          prompt,
          aiMockSummarizeText(group.category, group.articles)
        );
        const parsed = aiExtractJsonObject(raw);
        if (!parsed || !Array.isArray(parsed.bullets)) {
          const err = new Error("summarize_missing_bullets");
          err.code = "summarize_missing_bullets";
          throw err;
        }
        return raw;
      }, maxRetries);
      const parsed = aiExtractJsonObject(text);
      sumResults.push(
        aiSanitizeCategorySummary(group.category, parsed, group.articles)
      );
    } catch (err) {
      errors.push({
        stage: "summarize",
        category: group.category,
        error: (err && err.message) || String(err),
        code: err && err.code,
      });
      if (options.fallbackMockOnError || useMock) {
        const parsed = aiExtractJsonObject(
          aiMockSummarizeText(group.category, group.articles)
        );
        sumResults.push(
          aiSanitizeCategorySummary(group.category, parsed, group.articles)
        );
      }
    }
  }

  const briefingCategories = aiMergeBriefingCategories(sumResults);
  const ok = briefingCategories.length > 0;

  return {
    articles: applied.articles,
    dropped: applied.dropped,
    groups: groups,
    categories: briefingCategories,
    ai: {
      model: useMock ? "mock" : model,
      mock: useMock,
      thinkingLevel: thinkingLevel,
      categorizedCount: applied.stats.categorizedCount,
      droppedCount: applied.stats.droppedCount,
      lowConfidence: applied.stats.lowConfidence,
      groupCount: groups.length,
      summarizedCategories: briefingCategories.length,
      skippedCategories: skipped,
      errors: errors,
      categorizeStats: applied.stats,
      summarizeStats: sumResults.map(function (r) {
        return Object.assign({ category: r.category }, r.stats);
      }),
      rateLimit: limiter ? limiter.getStats() : { mock: true },
    },
    guard: {
      proceed: ok,
      reason: ok ? null : "ai_empty_briefing",
      skipLlm: false,
      skipPublish: !ok,
    },
  };
}


const input = $input.first().json || {};
const config = input.config || {};
const articles = Array.isArray(input.articles) ? input.articles : [];

const envKey =
  typeof $vars !== 'undefined' && $vars.GEMINI_API_KEY
    ? $vars.GEMINI_API_KEY
    : '';
const forceMock =
  (typeof $vars !== 'undefined' && String($vars.AI_MOCK || '').toLowerCase() === 'true') ||
  !envKey;

const result = await aiRunPipeline(articles, {
  categories: config.categories || [],
  llm: config.llm || {},
  apiKey: envKey,
  httpRequest: this.helpers.httpRequest.bind(this.helpers),
  mock: forceMock,
  fallbackMockOnError: forceMock,
});

return [
  {
    json: {
      runId: input.runId,
      runDate: input.runDate,
      triggeredAt: input.triggeredAt,
      mode: input.mode,
      timezone: input.timezone || config.timezone || 'Asia/Kolkata',
      config,
      sourceStatuses: input.sourceStatuses || [],
      collection: input.collection || {},
      corpus: input.corpus || {},
      articles: result.articles,
      dropped: result.dropped,
      categories: result.categories,
      ai: result.ai,
      guard: {
        ...(input.guard || {}),
        ...result.guard,
      },
      articleCount: (input.corpus && input.corpus.articleCount) || articles.length,
      dedupedCount: (input.corpus && input.corpus.dedupedCount) || 0,
      sourceSuccessCount:
        (input.corpus && input.corpus.sourceSuccessCount) || 0,
      phase: 'phase4-ai',
      nextPhaseHint: result.guard.proceed
        ? 'Phase 6 will format canonical briefing JSON and publish'
        : 'AI produced no grounded categories — skip publish (keep last good summary)',
    },
  },
];

// Phase 6 — Build canonical schemaVersion:1 briefing JSON
const FORMAT_DEFAULT_TITLE = "India News Summary";

function formatToAsiaKolkataIso(input) {
  if (input == null || input === "") return null;
  const d = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return null;

  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(d)
      .filter(function (p) {
        return p.type !== "literal";
      })
      .map(function (p) {
        return [p.type, p.value];
      })
  );

  return (
    parts.year +
    "-" +
    parts.month +
    "-" +
    parts.day +
    "T" +
    parts.hour +
    ":" +
    parts.minute +
    ":" +
    parts.second +
    "+05:30"
  );
}

function formatMapFailedSources(input) {
  const collection = input.collection || {};
  const corpus = input.corpus || {};
  const raw =
    collection.failedSources ||
    corpus.failedSources ||
    (Array.isArray(input.sourceStatuses)
      ? input.sourceStatuses
          .filter(function (s) {
            return s.status === "failed";
          })
          .map(function (s) {
            return {
              sourceId: s.sourceId,
              sourceName: s.sourceName,
              error: s.error,
            };
          })
      : []);

  return raw.map(function (entry) {
    return {
      id: entry.id || entry.sourceId || "unknown",
      name: entry.name || entry.sourceName || "Unknown source",
      error: entry.error || "unknown",
    };
  });
}

function formatSanitizeCategories(categories) {
  return (categories || [])
    .map(function (cat) {
      return {
        category: cat.category,
        bullets: (cat.bullets || [])
          .map(function (bullet) {
            return {
              summary: String(bullet.summary || "").trim(),
              sources: (bullet.sources || [])
                .map(function (source) {
                  return {
                    title: String(source.title || "").trim(),
                    url: String(source.url || "").trim(),
                  };
                })
                .filter(function (source) {
                  return (
                    source.title && /^https?:\/\//i.test(source.url)
                  );
                }),
            };
          })
          .filter(function (bullet) {
            return bullet.summary && bullet.sources.length > 0;
          }),
      };
    })
    .filter(function (cat) {
      return cat.bullets.length > 0;
    });
}

function formatResolveGeneratedAt(input, now) {
  const candidates = [input.triggeredAt, input.generatedAt, now || new Date()];
  for (let i = 0; i < candidates.length; i++) {
    const formatted = formatToAsiaKolkataIso(candidates[i]);
    if (formatted) return formatted;
  }
  return formatToAsiaKolkataIso(now || new Date());
}

function formatBuildBriefing(input, options) {
  options = options || {};
  const config = input.config || {};
  const collection = input.collection || {};
  const corpus = input.corpus || {};
  const categories = formatSanitizeCategories(input.categories);
  const sourcesConfigured =
    collection.sourcesConfigured != null
      ? collection.sourcesConfigured
      : Array.isArray(config.sources)
        ? config.sources.length
        : 0;
  const sourcesSucceeded =
    collection.sourcesSucceeded != null
      ? collection.sourcesSucceeded
      : corpus.sourceSuccessCount != null
        ? corpus.sourceSuccessCount
        : 0;
  const articleCount =
    corpus.articleCount != null
      ? corpus.articleCount
      : collection.articleCount != null
        ? collection.articleCount
        : input.articleCount != null
          ? input.articleCount
          : 0;

  const briefing = {
    schemaVersion: 1,
    runId: input.runId,
    generatedAt: formatResolveGeneratedAt(input, options.now),
    timezone: input.timezone || config.timezone || "Asia/Kolkata",
    title: options.title || FORMAT_DEFAULT_TITLE,
    status: "ok",
    meta: {
      sourcesConfigured: sourcesConfigured,
      sourcesSucceeded: sourcesSucceeded,
      articleCount: articleCount,
      failedSources: formatMapFailedSources(input),
    },
    categories: categories,
  };

  const proceed =
    briefing.status === "ok" &&
    briefing.categories.length > 0 &&
    Boolean(briefing.runId);

  return {
    briefing: briefing,
    guard: {
      proceed: proceed,
      reason: proceed ? null : "no_publishable_categories",
      skipPublish: !proceed,
    },
  };
}


const input = $input.first().json || {};
const formatted = formatBuildBriefing(input);

return [
  {
    json: {
      ...input,
      briefing: formatted.briefing,
      guard: {
        ...(input.guard || {}),
        ...formatted.guard,
      },
      phase: 'phase6-format',
      nextPhaseHint: formatted.guard.proceed
        ? 'Publish PUT to website API'
        : 'No publishable categories — skip publish (keep last good summary)',
    },
  },
];

// Phase 6/7 — PUT briefing to website API with retry/backoff
const input = $input.first().json || {};
const config = input.config || {};
const website = config.website || {};
const briefing = input.briefing;

if (!briefing || !Array.isArray(briefing.categories) || briefing.categories.length === 0) {
  return [
    {
      json: {
        ...input,
        phase: 'phase6-publish-skipped',
        outcome: 'skipped_publish',
        message: 'No briefing to publish — keeping last good website summary.',
      },
    },
  ];
}

const publishUrl = website.publishUrl;
if (!publishUrl) {
  throw new Error('Missing config.website.publishUrl');
}

const apiKey =
  typeof $vars !== 'undefined' && $vars.PUBLISH_API_KEY
    ? $vars.PUBLISH_API_KEY
    : '';
if (!apiKey) {
  throw new Error('Missing n8n Variable PUBLISH_API_KEY ($vars.PUBLISH_API_KEY)');
}

const maxAttempts = 3;
const backoffMs = [2000, 5000, 10000];
let lastError = null;
let lastStatus = null;

for (let attempt = 0; attempt < maxAttempts; attempt++) {
  try {
    const res = await this.helpers.httpRequest({
      method: website.publishMethod || 'PUT',
      url: publishUrl,
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + apiKey,
      },
      body: briefing,
      returnFullResponse: true,
      timeout: 30000,
      ignoreHttpStatusErrors: true,
    });

    const statusCode = res.statusCode ?? res.status ?? 0;
    lastStatus = statusCode;
    let body = res.body ?? res.data ?? '';
    if (body && typeof body === 'object') {
      body = JSON.stringify(body);
    }

    if (statusCode >= 200 && statusCode < 300) {
      let parsed = null;
      try {
        parsed = body ? JSON.parse(body) : null;
      } catch {
        parsed = { raw: body };
      }

      return [
        {
          json: {
            ...input,
            publish: {
              ok: true,
              statusCode,
              attempt: attempt + 1,
              response: parsed,
            },
            phase: 'phase6-published',
            outcome: 'published',
            message: 'Briefing published to website API.',
          },
        },
      ];
    }

    lastError = 'HTTP ' + statusCode + (body ? ': ' + String(body).slice(0, 200) : '');
    const retriable = statusCode === 408 || statusCode === 429 || statusCode >= 500;
    if (retriable && attempt < maxAttempts - 1) {
      await new Promise((r) => setTimeout(r, backoffMs[attempt] || 5000));
      continue;
    }

    throw new Error('Publish failed: ' + lastError);
  } catch (err) {
    lastError = (err && err.message) || String(err);
    if (attempt < maxAttempts - 1) {
      await new Promise((r) => setTimeout(r, backoffMs[attempt] || 5000));
      continue;
    }
  }
}

throw new Error(
  'Publish failed after ' +
    maxAttempts +
    ' attempts (status=' +
    (lastStatus == null ? 'n/a' : lastStatus) +
    '): ' +
    (lastError || 'unknown')
);

// Phase 3 — Empty corpus guard: do not call LLM; do not overwrite website
const input = $input.first().json || {};

return [
  {
    json: {
      runId: input.runId,
      runDate: input.runDate,
      triggeredAt: input.triggeredAt,
      mode: input.mode,
      timezone: input.timezone,
      config: input.config,
      sourceStatuses: input.sourceStatuses || [],
      collection: input.collection || {},
      articles: [],
      categories: [],
      corpus: input.corpus || {},
      guard: input.guard || {
        proceed: false,
        reason: 'empty_corpus',
        skipLlm: true,
        skipPublish: true,
      },
      articleCount: 0,
      dedupedCount: (input.corpus && input.corpus.dedupedCount) || 0,
      sourceSuccessCount: (input.corpus && input.corpus.sourceSuccessCount) || 0,
      phase: 'phase3-empty-guard',
      outcome: 'skipped_llm_and_publish',
      message:
        'Empty corpus after normalize/dedupe — keeping last good website summary; no LLM; no publish overwrite.',
    },
  },
];

// Phase 4 — AI empty/failed briefing: do not overwrite website
const input = $input.first().json || {};

return [
  {
    json: {
      runId: input.runId,
      runDate: input.runDate,
      triggeredAt: input.triggeredAt,
      mode: input.mode,
      timezone: input.timezone,
      config: input.config,
      sourceStatuses: input.sourceStatuses || [],
      collection: input.collection || {},
      corpus: input.corpus || {},
      articles: input.articles || [],
      categories: [],
      ai: input.ai || {},
      guard: {
        proceed: false,
        reason: (input.guard && input.guard.reason) || 'ai_empty_briefing',
        skipLlm: false,
        skipPublish: true,
      },
      articleCount: input.articleCount || 0,
      phase: 'phase4-ai-failed-guard',
      outcome: 'skipped_publish',
      message:
        'AI stage produced no publishable categories — keeping last good website summary; no publish overwrite.',
    },
  },
];
